package com.kachat.app.util

import com.kachat.app.services.Outpoint
import com.kachat.app.services.RawInput
import com.kachat.app.services.RawOutputWithVersion
import com.kachat.app.services.RawTransaction
import com.kachat.app.services.ScriptPublicKeyWithVersion
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * A transaction's id has to be the one the chain will show, because a scheduled post is keyed on
 * it before it is submitted (KAPOSTS_INDEXER.md section 5.10). These are two real KaChat
 * self-sends, read back off the chain (api.kaspa.org), with the ids the network gave them.
 */
class KaspaTransactionIdTest {

    @Test
    fun `computes the id real on-chain KaChat transactions were given`() {
        val tx1 = RawTransaction(
            version = 0,
            inputs = listOf(
            RawInput(previousOutpoint = Outpoint(transactionId = "debcc13f410fd3facac1f91978941d223ef05861c5e8470c1144b0598c820d13", index = 0), signatureScript = "", sequence = 0, sigOpCount = 1)
            ),
            outputs = listOf(
            RawOutputWithVersion(amount = 999033585L, scriptPublicKey = ScriptPublicKeyWithVersion(scriptPublicKey = "20f75c1cb050d94291daa70c338be91073b2f1cee3a44ac690050ee8a96812658dac", version = 0))
            ),
            lockTime = 0,
            subnetworkId = "0000000000000000000000000000000000000000",
            gas = 0,
            payload = "",
        )
        assertEquals("f28587d7ac7ba1f8545e3b4f18dfc24f03160fa596feccbfb3da964272ca054b", KaspaTransactionId.compute(tx1))

        val tx2 = RawTransaction(
            version = 0,
            inputs = listOf(
            RawInput(previousOutpoint = Outpoint(transactionId = "c33060874fd16bf318971c3e7bf2b9240cd5553b933628b8a5cb13670767a911", index = 0), signatureScript = "", sequence = 0, sigOpCount = 1)
            ),
            outputs = listOf(
            RawOutputWithVersion(amount = 999231388L, scriptPublicKey = ScriptPublicKeyWithVersion(scriptPublicKey = "20f75c1cb050d94291daa70c338be91073b2f1cee3a44ac690050ee8a96812658dac", version = 0))
            ),
            lockTime = 0,
            subnetworkId = "0000000000000000000000000000000000000000",
            gas = 0,
            payload = "",
        )
        assertEquals("debcc13f410fd3facac1f91978941d223ef05861c5e8470c1144b0598c820d13", KaspaTransactionId.compute(tx2))
    }
}
